# Precise monochrome system. D2 owns all placement and connector routing.
vars: {
  d2-config: {
    layout-engine: elk
    theme-id: 0
    pad: 24
  }
  edge-style: {
    stroke: "#353535"
    stroke-width: 1
    border-radius: 0
    font-color: "#262626"
    font-size: 16
    font: mono
    italic: false
    bold: false
  }
}
style.fill: "#FFFFFF"
***.class: state
***.style: {
  font-color: "#171717"
  stroke-width: 1
  border-radius: 0
  shadow: false
  bold: false
}
classes: {
