    label.near: top-left
    style.fill: "#FAFAFA"
    style.stroke: "#CECECE"
    style.font: mono
    style.font-size: 16
  }
  state: {
    style.font-size: 18
    style.fill: "#FFFFFF"
    style.stroke: "#686868"
  }
  durable: {
    style.font-size: 18
    style.fill: "#FFFFFF"
    style.stroke: "#353535"
  }
  caution: {
    style.font-size: 18
    style.fill: "#FFFFFF"
    style.stroke: "#353535"
    style.stroke-dash: 4
  }
}

